package com.example.auth.company;
import com.example.auth.common.*;import com.example.auth.entity.*;import com.example.auth.repository.AccountRepository;import com.example.auth.integration.BranchDirectory;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.net.URI;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional
public class SettingsService {
 private final AccountRepository accounts;private final EntityManager em;private final BranchDirectory branches;
 private Account actor(String username){var a=accounts.findByUsername(username).orElseThrow(ApiException::missing);if(!Boolean.TRUE.equals(a.getStatus())||a.isMustChangePassword()||a.getRole()==Role.STUDENT)throw ApiException.forbidden();return a;}
 public record PreferencesRequest(@NotNull Long version,boolean compactTables,int pageSize,@NotBlank String calendarView,Long defaultBranchId){}
 public record ProfileRequest(@NotNull Long version,@NotBlank @Size(max=120)String name,@Size(max=500)String logoUrl,@Size(max=255)String address,@Email @Size(max=100)String email,@Size(max=30)String phone){}
 @Transactional(readOnly=true) public UserPreferences preferences(String username){var a=actor(username);var p=em.find(UserPreferences.class,a.getId());if(p==null){p=new UserPreferences();p.setAccountId(a.getId());}if(p.getDefaultBranchId()!=null&&!a.activeBranchIds().contains(p.getDefaultBranchId())){var copy=new UserPreferences();copy.setAccountId(p.getAccountId());copy.setVersion(p.getVersion());copy.setCompactTables(p.isCompactTables());copy.setPageSize(p.getPageSize());copy.setCalendarView(p.getCalendarView());return copy;}return p;}
 public UserPreferences save(String username,PreferencesRequest r){var a=actor(username);a=accounts.lock(a.getId()).orElseThrow(ApiException::missing);var p=em.find(UserPreferences.class,a.getId());if(r.version()==null||r.version()!=(p==null?0:p.getVersion()))throw ApiException.conflict("Cài đặt đã thay đổi; hãy tải lại");if(!Set.of(10,20,50).contains(r.pageSize())||!Set.of("week","day").contains(r.calendarView()))throw ApiException.bad("Tùy chọn hiển thị không hợp lệ");if(r.defaultBranchId()!=null){if(a.getRole()==Role.SUPER_ADMIN||!a.activeBranchIds().contains(r.defaultBranchId()))throw ApiException.forbidden();branches.requireActive(r.defaultBranchId());}boolean fresh=p==null;if(fresh){p=new UserPreferences();p.setAccountId(a.getId());}p.setCompactTables(r.compactTables());p.setPageSize(r.pageSize());p.setCalendarView(r.calendarView());p.setDefaultBranchId(r.defaultBranchId());p.setVersion(Math.addExact(p.getVersion(),1));if(fresh)em.persist(p);em.flush();return p;}
 @Transactional(readOnly=true) public CompanyProfile profile(String username){actor(username);var p=em.find(CompanyProfile.class,1L);if(p==null){p=new CompanyProfile();p.setId(1L);}return p;}
 private String text(String s){return s==null||s.isBlank()?null:s.trim();}
 public CompanyProfile profile(String username,ProfileRequest r){var a=actor(username);if(a.getRole()!=Role.SUPER_ADMIN)throw ApiException.forbidden();accounts.lock(a.getId()).orElseThrow(ApiException::missing);var p=em.find(CompanyProfile.class,1L,LockModeType.PESSIMISTIC_WRITE);boolean fresh=p==null;if(fresh){p=new CompanyProfile();p.setId(1L);em.persist(p);}if(r.version()==null||p.getVersion()!=r.version())throw ApiException.conflict("Thông tin đã thay đổi; hãy tải lại");if(fresh)p.setVersion(1);String logo=text(r.logoUrl());if(logo!=null){try{var uri=URI.create(logo);if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null)throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw ApiException.bad("Logo phải là địa chỉ HTTPS hợp lệ");}}p.setName(r.name().trim());p.setLogoUrl(logo);p.setAddress(text(r.address()));p.setEmail(text(r.email()));p.setPhone(text(r.phone()));a.recordSecurityEvent("COMPANY_PROFILE_UPDATED",a.getId(),"Cập nhật thông tin công khai của trung tâm");em.flush();return p;}
}
